import { useCallback, useId, useState } from 'react';
import { Button, Dialog } from '@jinx-ui/react';

type DeleteProjectProps = {
  onConfirm: () => void;
};

export default function DeleteProject({ onConfirm }: DeleteProjectProps) {
  const [open, setOpen] = useState(false);
  const titleId = useId();
  const descriptionId = useId();

  const handleConfirm = useCallback(() => {
    setOpen(false);
    onConfirm();
  }, [onConfirm]);

  return (
    <>
      <Button variant="danger" onClick={() => setOpen(true)}>
        Удалить проект
      </Button>

      <Dialog
        open={open}
        onOpenChange={setOpen}
        labelledBy={titleId}
        describedBy={descriptionId}
        aria-modal="true"
      >
        <div
          className="jx-stack"
          style={{ display: 'grid', gap: 'var(--jx-space-4)' }}
        >
          <h2 id={titleId} className="jx-heading">
            Удалить проект?
          </h2>

          <p
            id={descriptionId}
            className="jx-text jx-text-muted"
            style={{ color: 'var(--jx-fg-muted)' }}
          >
            Проект и все связанные с ним данные будут удалены безвозвратно. Это
            действие нельзя отменить.
          </p>

          <div
            className="jx-cluster"
            style={{
              display: 'flex',
              gap: 'var(--jx-space-2)',
              justifyContent: 'flex-end',
            }}
          >
            <Button variant="ghost" onClick={() => setOpen(false)}>
              Отмена
            </Button>
            <Button variant="danger" onClick={handleConfirm}>
              Удалить
            </Button>
          </div>
        </div>
      </Dialog>
